//! Global design-token theme overrides (`STYLE::SET_DESIGN_TOKEN`).
//!
//! A [`Theme`] is a batch of **global, renderer-wide token overrides** — base
//! (light) values and `dark.*` variants (spec/TOKENS.md). It is emitted once at
//! mount via [`Engine::apply_theme`](crate::Engine::apply_theme); overrides are
//! renderer state, so they **never re-emit nodes** and never participate in the
//! diff.

use alloc::string::{String, ToString};
use alloc::vec::Vec;

use pathland_core::tokens::TokenValue;

/// A batch of global design-token overrides to emit before the tree.
#[derive(Debug, Clone, Default)]
pub struct Theme {
    overrides: Vec<(String, TokenValue)>,
}

impl Theme {
    /// An empty theme.
    pub fn new() -> Self {
        Self::default()
    }

    /// Override a **base (light)** token with a packed sRGB `0xAARRGGBB` color.
    pub fn color(mut self, path: &str, argb: u32) -> Self {
        self.push(path, TokenValue::Color(argb));
        self
    }

    /// Override the **dark variant** of a token with a packed sRGB color.
    pub fn dark_color(mut self, path: &str, argb: u32) -> Self {
        self.push_dark(path, TokenValue::Color(argb));
        self
    }

    /// Override a **base (light)** token with an `F32` value (lengths are in
    /// device pixels).
    pub fn f32(mut self, path: &str, value: f32) -> Self {
        self.push(path, TokenValue::F32(value));
        self
    }

    /// Override the **dark variant** of a token with an `F32` value.
    pub fn dark_f32(mut self, path: &str, value: f32) -> Self {
        self.push_dark(path, TokenValue::F32(value));
        self
    }

    /// Override a **base (light)** token with a `U32` value.
    pub fn u32(mut self, path: &str, value: u32) -> Self {
        self.push(path, TokenValue::U32(value));
        self
    }

    /// Override a **base (light)** token with a `U8` value.
    pub fn u8(mut self, path: &str, value: u8) -> Self {
        self.push(path, TokenValue::U8(value));
        self
    }

    /// Override a **base (light)** token with a `STRING` value (e.g.
    /// `font.body.family`). Rides the arena as a `STRING`-valued override.
    pub fn string(mut self, path: &str, value: &str) -> Self {
        self.push(path, TokenValue::Str(value.to_string()));
        self
    }

    /// Override the **dark variant** of a token with a `STRING` value.
    pub fn dark_string(mut self, path: &str, value: &str) -> Self {
        self.push_dark(path, TokenValue::Str(value.to_string()));
        self
    }

    /// Append a raw override with an explicit full path (may include a
    /// `dark.` prefix).
    pub fn override_token(mut self, path: &str, value: TokenValue) -> Self {
        self.overrides.push((path.to_string(), value));
        self
    }

    fn push(&mut self, path: &str, value: TokenValue) {
        self.overrides.push((path.to_string(), value));
    }

    fn push_dark(&mut self, path: &str, value: TokenValue) {
        let dark = if path.starts_with("dark.") {
            path.to_string()
        } else {
            format!("dark.{path}")
        };
        self.overrides.push((dark, value));
    }

    /// The accumulated overrides (path, value) in insertion order.
    pub fn iter(&self) -> impl Iterator<Item = (&str, &TokenValue)> {
        self.overrides.iter().map(|(p, v)| (p.as_str(), v))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Engine;
    use pathland_core::{init_memory, tokens::TokenValue, value_type, Guest, Host, MemoryLayout};

    #[test]
    fn dark_builder_prepends_dark_prefix() {
        let theme = Theme::new()
            .color("color.primary", 0xFF2563EB)
            .dark_color("color.primary", 0xFF60A5FA)
            .string("font.body.family", "Inter");
        let pairs: Vec<_> = theme.iter().collect();
        assert_eq!(pairs[0], ("color.primary", &TokenValue::Color(0xFF2563EB)));
        assert_eq!(pairs[1], ("dark.color.primary", &TokenValue::Color(0xFF60A5FA)));
        assert_eq!(pairs[2], ("font.body.family", &TokenValue::Str("Inter".into())));
    }

    #[test]
    fn apply_theme_emits_set_design_token_opcodes() {
        let layout = MemoryLayout::default();
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);

        let mut guest = Guest::new(&mut mem, &layout);
        guest.begin_frame();
        let mut engine = Engine::new();
        engine
            .apply_theme(
                &Theme::new()
                    .color("color.primary", 0xFF2563EB)
                    .dark_color("color.primary", 0xFF60A5FA)
                    .string("font.body.family", "Inter"),
                &mut guest,
            )
            .unwrap();
        guest.end_frame();

        let mut host = Host::new(&mut mem, &layout);
        let frame = &host.frames()[0];
        let ops: Vec<_> = frame.opcodes().collect();
        assert_eq!(ops.len(), 3, "one SET_DESIGN_TOKEN per override");
        for op in &ops {
            assert_eq!(op.category(), pathland_core::category::STYLE);
            assert_eq!(op.command(), pathland_core::style::SET_DESIGN_TOKEN);
        }
        // The two color overrides ride valueType COLOR with the packed argb.
        assert_eq!(ops[0].b(), u32::from(value_type::COLOR));
        assert_eq!(ops[0].c(), 0xFF2563EB);
        assert_eq!(ops[1].b(), u32::from(value_type::COLOR));
        assert_eq!(ops[1].c(), 0xFF60A5FA);
        // The string value rides valueType STRING with C = arena offset of "Inter".
        assert_eq!(ops[2].b(), u32::from(value_type::STRING));
        assert_eq!(frame.arena_str(ops[2].c()).unwrap(), "Inter");
        // Paths resolve from the arena.
        assert_eq!(frame.arena_str(ops[0].a()).unwrap(), "color.primary");
        assert_eq!(frame.arena_str(ops[1].a()).unwrap(), "dark.color.primary");
        assert_eq!(frame.arena_str(ops[2].a()).unwrap(), "font.body.family");
    }
}

