package com.pathland.view;

import com.pathland.view.emit.OpcodeSink;

import java.util.ArrayList;
import java.util.List;

/**
 * A batch of **global, renderer-wide design-token overrides**
 * ({@code STYLE::SET_DESIGN_TOKEN}, spec/TOKENS.md): base (light) values and
 * {@code dark.}-prefixed variants. Emitted once at mount via
 * {@link #emit(OpcodeSink)} — overrides are renderer state, so they never
 * re-emit nodes and never participate in the diff.
 *
 * <p>Builder methods are self-returning for chaining:
 * <pre>{@code
 * Theme theme = new Theme()
 *     .color("color.primary", 0xFF2563EB)
 *     .darkColor("color.primary", 0xFF60A5FA)
 *     .f32("space.base", 4.0f)
 *     .string("font.body.family", "Inter");
 * theme.emit(sink);
 * }</pre>
 */
public final class Theme {

    private record Override(String path, int valueType, Object value) {}

    private final List<Override> overrides = new ArrayList<>();

    /** Override a **base (light)** token with a packed sRGB {@code 0xAARRGGBB} color. */
    public Theme color(String path, int argb) {
        return push(path, ValueTypes.COLOR, Color.of(argb));
    }

    /** Override the **dark variant** of a token with a packed sRGB color. */
    public Theme darkColor(String path, int argb) {
        return push(dark(path), ValueTypes.COLOR, Color.of(argb));
    }

    /** Override a **base (light)** token with an F32 value. */
    public Theme f32(String path, float value) {
        return push(path, ValueTypes.F32, value);
    }

    /** Override the **dark variant** of a token with an F32 value. */
    public Theme darkF32(String path, float value) {
        return push(dark(path), ValueTypes.F32, value);
    }

    /** Override a **base (light)** token with a U32 value. */
    public Theme u32(String path, int value) {
        return push(path, ValueTypes.U32, value);
    }

    /** Override a **base (light)** token with a U8 value. */
    public Theme u8(String path, int value) {
        return push(path, ValueTypes.U8, value);
    }

    /** Override a **base (light)** token with a STRING value (e.g. {@code font.body.family}). */
    public Theme string(String path, String value) {
        return push(path, ValueTypes.STRING, value);
    }

    /** Override the **dark variant** of a token with a STRING value. */
    public Theme darkString(String path, String value) {
        return push(dark(path), ValueTypes.STRING, value);
    }

    private static String dark(String path) {
        return path.startsWith("dark.") ? path : "dark." + path;
    }

    private Theme push(String path, int valueType, Object value) {
        overrides.add(new Override(path, valueType, value));
        return this;
    }

    /** Emit all overrides as one frame of {@code STYLE::SET_DESIGN_TOKEN} opcodes. */
    public void emit(OpcodeSink sink) {
        sink.beginFrame();
        for (Override o : overrides) {
            sink.setDesignToken(o.path(), o.valueType(), o.value());
        }
        sink.endFrame();
    }
}

