package com.pathland.demo;

import com.pathland.view.Theme;

/**
 * The demo's global theme: a batch of {@code STYLE::SET_DESIGN_TOKEN} overrides
 * (base = light, {@code dark.*} = dark variant, spec/TOKENS.md). The renderer
 * re-resolves them under the platform's color scheme, so the HTML/JS DOM demo
 * re-themes under {@code prefers-color-scheme: dark} and a native GTK renderer
 * under its dark variant — with no re-emission.
 */
