//! GTK-native design-token defaults + color-scheme detection (spec/TOKENS.md).
//!
//! The renderer owns default token values and the effective color scheme.
//! Tier-1 defaults start as **concrete platform-appropriate fallbacks**
//! ([`concrete_default_tables`]); when a real widget exists, the tokens that
//! the current GTK theme can resolve are replaced with **native colors** via
//! [`gtk::StyleContext::lookup_color`] of the theme's named colors
//! (`@theme_*`, `@borders`, `@success_color`, …). Headless / theme-missing →
//! pure concrete fallback, which keeps tests deterministic.

use std::collections::BTreeMap;

use pathland_core::tokens::{Scheme, TokenValue};

use crate::host::concrete_default_tables;

/// GTK theme named color → canonical Tier-1 token path. `lookup_color` returns
/// `None` when the theme doesn't define a name, in which case the concrete
/// fallback is kept.
const NAMED_COLORS: &[(&str, &str)] = &[
    ("theme_bg_color", "color.background"),
    ("theme_base_color", "color.surface"),
    ("theme_fg_color", "color.text.primary"),
    ("theme_unfocused_fg_color", "color.text.secondary"),
    ("theme_selected_bg_color", "color.accent"),
    ("theme_selected_bg_color", "color.primary"),
    ("theme_selected_fg_color", "color.text.onPrimary"),
    ("borders", "color.border"),
    ("success_color", "color.success"),
    ("warning_color", "color.warning"),
    ("error_color", "color.danger"),
];

/// The effective color scheme from the native GTK variant (`prefer-dark` or a
/// `-dark` theme name). Falls back to light when no settings object exists.
pub fn active_scheme() -> Scheme {
    gtk::Settings::default()
        .map(|s| scheme_from_settings(&s))
        .unwrap_or(Scheme::Light)
}

/// Derive the effective scheme from a `GtkSettings` object.
#[allow(deprecated)] // gtk_application_prefer_dark_theme is deprecated but the 4.14 `gtk-color-scheme` isn't in this binding
pub fn scheme_from_settings(settings: &gtk::Settings) -> Scheme {
    let dark = settings.gtk_application_prefer_dark_theme()
        || settings
            .gtk_theme_name()
            .as_deref()
            .map_or(false, |name| name.ends_with("-dark"));
    if dark {
        Scheme::Dark
    } else {
        Scheme::Light
    }
}

/// Build the Tier-1 default tables (light + dark), replacing the tokens the
/// given style context's current theme can resolve with native colors for the
/// given scheme. GTK exposes one theme at a time, so only the *active* scheme's
/// defaults are native; the other scheme keeps its concrete fallback.
pub fn enrich_defaults(
    ctx: &gtk::StyleContext,
    scheme: Scheme,
) -> (BTreeMap<String, TokenValue>, BTreeMap<String, TokenValue>) {
    let (mut base, mut dark) = concrete_default_tables();
    let target = match scheme {
        Scheme::Dark => &mut dark,
        Scheme::Light => &mut base,
    };
    for (name, path) in NAMED_COLORS {
        if let Some(argb) = lookup_color(ctx, name) {
            target.insert((*path).to_string(), TokenValue::Color(argb));
        }
    }
    (base, dark)
}

/// `StyleContext::lookup_color` of a named theme color, packed to `0xAARRGGBB`.
fn lookup_color(ctx: &gtk::StyleContext, name: &str) -> Option<u32> {
    ctx.lookup_color(name).map(|rgba| {
        let a = (rgba.alpha() * 255.0).round().clamp(0.0, 255.0) as u32;
        let r = (rgba.red() * 255.0).round() as u32;
        let g = (rgba.green() * 255.0).round() as u32;
        let b = (rgba.blue() * 255.0).round() as u32;
        (a << 24) | (r << 16) | (g << 8) | b
    })
}

