    use super::*;

    #[test]
    fn named_color_mapping_covers_core_tokens() {
        let paths: Vec<&str> = NAMED_COLORS.iter().map(|(_, p)| *p).collect();
        for core in [
            "color.background",
            "color.surface",
            "color.text.primary",
            "color.accent",
            "color.primary",
            "color.border",
            "color.success",
            "color.warning",
            "color.danger",
        ] {
            assert!(paths.contains(&core), "missing GTK-native mapping for {core}");
        }
    }

    #[test]
    fn enrich_defaults_keeps_fallback_when_theme_resolves_nothing() {
        // A fresh, unparented style context has no theme → lookup returns None
        // → the concrete fallback tables are returned unchanged.
        let (base, dark) = enrich_defaults(&gtk::StyleContext::builder().build(), Scheme::Light);
        assert_eq!(
            base.get("color.primary"),
            Some(&TokenValue::Color(0xFF_2563EB)),
            "fallback primary kept"
