pub fn scheme_from_settings(settings: &gtk::Settings) -> Scheme {
    let dark = settings.is_gtk_application_prefer_dark_theme()
        || settings
            .gtk_theme_name()
            .as_deref()
            .map_or(false, |name| name.ends_with("-dark"));
    if dark {
        Scheme::Dark
    } else {
        Scheme::Light
    }
}

