package com.pathland.view;

import com.pathland.view.emit.OpcodeSink;

/**
 * A set of **global, renderer-wide design-token overrides**
 * ({@code STYLE::SET_DESIGN_TOKEN}, spec/TOKENS.md). Overrides are renderer
 * state, so they never re-emit nodes and never participate in the diff.
 *
 * <p>Two implementations exist: a single-value {@link Theme} (light/one scheme)
 * and an {@link AdaptiveTheme} composed of a light + dark {@link Theme} pair.
 */
public interface ThemeData {

    /** Emit the overrides into an already-open frame (no frame boundaries). */
    void emitInto(OpcodeSink sink);

    /** Emit all overrides as one frame of {@code STYLE::SET_DESIGN_TOKEN} opcodes. */
    default void emit(OpcodeSink sink) {
        sink.beginFrame();
        emitInto(sink);
        sink.endFrame();
    }
}

package com.pathland.view;

import com.pathland.view.emit.OpcodeSink;

import java.util.ArrayList;
import java.util.List;

/**
 * A batch of **global, renderer-wide design-token overrides** for a single
 * scheme ({@code STYLE::SET_DESIGN_TOKEN}, spec/TOKENS.md). Every builder
 * defines exactly **one value** — combine a light and a dark {@link Theme} via
 * {@link AdaptiveTheme} for adaptive theming (the dark one is emitted with the
 * {@code dark.} prefix).
 *
 * <p>Builder methods are self-returning for chaining:
 * <pre>{@code
 * Theme light = new Theme()
 *     .color("color.primary", 0xFF2563EB)
 *     .f32("space.base", 4.0f)
 *     .string("font.body.family", "Inter");
 * Theme dark = new Theme().color("color.primary", 0xFF60A5FA);
 * new AdaptiveTheme(light, dark).emit(sink);
 * }</pre>
 */
public final class Theme implements ThemeData {

    /** A single token override (path, wire value type, typed value). */
    record Override(String path, int valueType, Object value) {}

    private final List<Override> overrides = new ArrayList<>();

    /** Override a token with a packed sRGB {@code 0xAARRGGBB} color. */
    public Theme color(String path, int argb) {
        return push(path, ValueTypes.COLOR, Color.of(argb));
    }

    /** Override a token with an F32 value. */
    public Theme f32(String path, float value) {
        return push(path, ValueTypes.F32, value);
    }

    /** Override a token with a U32 value. */
    public Theme u32(String path, int value) {
        return push(path, ValueTypes.U32, value);
    }

    /** Override a token with a U8 value. */
    public Theme u8(String path, int value) {
        return push(path, ValueTypes.U8, value);
    }

    /** Override a token with a STRING value (e.g. {@code font.body.family}). */
    public Theme string(String path, String value) {
        return push(path, ValueTypes.STRING, value);
    }

    private Theme push(String path, int valueType, Object value) {
        overrides.add(new Override(path, valueType, value));
        return this;
    }

    /** The accumulated overrides (package-private for {@link AdaptiveTheme}). */
    List<Override> overrides() {
        return overrides;
    }

    @Override
    public void emitInto(OpcodeSink sink) {
        for (Override o : overrides) {
            sink.setDesignToken(o.path(), o.valueType(), o.value());
        }
    }
}

package com.pathland.view;

import com.pathland.view.emit.OpcodeSink;

/**
 * An **adaptive theme**: a light ({@code Theme}) and a dark ({@code Theme})
 * pair. Emitting it writes the light theme's overrides as base tokens and the
 * dark theme's overrides with the {@code dark.} scheme prefix, so the renderer
 * resolves each against the platform's effective color scheme (spec/TOKENS.md).
 *
 * <pre>{@code
 * Theme light = new Theme().color("color.primary", 0xFF2563EB);
 * Theme dark  = new Theme().color("color.primary", 0xFF60A5FA);
 * new AdaptiveTheme(light, dark).emit(sink);
 * }</pre>
 */
public final class AdaptiveTheme implements ThemeData {

    private final Theme light;
    private final Theme dark;

    /** Compose a light and a dark theme. */
    public AdaptiveTheme(Theme light, Theme dark) {
        this.light = light;
        this.dark = dark;
    }

    /** The light (base) theme. */
    public Theme light() {
        return light;
    }

    /** The dark theme (emitted with the {@code dark.} scheme prefix). */
    public Theme dark() {
        return dark;
    }

    @Override
    public void emitInto(OpcodeSink sink) {
        light.emitInto(sink);
        for (Theme.Override o : dark.overrides()) {
            sink.setDesignToken(dark(o.path()), o.valueType(), o.value());
        }
    }

    private static String dark(String path) {
        return path.startsWith("dark.") ? path : "dark." + path;
    }
}

